#!/usr/bin/env node
// Builds ONE paste-safe SQL file that applies a migration to hosted Supabase and proves the result, so Ryan's hosted
// step is a single paste and a single reply (workflow improvement after FFH-P09).
//
//   node scripts/hosted/build-apply.mjs supabase/migrations/<version>_<name>.sql [--expected <parity file>] [--out <file>]
//
// The generated file runs in ONE transaction:
//   1. pre-check: hosted has exactly the migrations before this one and has not recorded this version;
//   2. the migration itself (its own begin;/commit; lines are removed);
//   3. records the version in supabase_migrations.schema_migrations;
//   4. paste repair: re-creates any function whose body picked up CR characters from the browser (strip-cr.sql);
//   5. optional phase checks from scripts/hosted/checks/<version>.sql (a SELECT returning check_name, ok);
//   6. parity: every section of scripts/rls-local/parity.sql must equal the committed expected fingerprint.
// If anything fails, it raises one error naming every failed check and NOTHING is applied. On success the last
// result is a table of PASS rows. It never reads household rows except through a phase check's aggregate counts.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { basename, dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repo = resolve(dirname(fileURLToPath(import.meta.url)), "../..");

export function buildApply({ migrationPath, migrationSql, paritySql, expectedText, stripCrSql, checksSql = null }) {
  const file = basename(migrationPath);
  const match = /^(\d{8,14})_([a-z0-9_]+)\.sql$/.exec(file);
  if (!match) throw new Error(`Unexpected migration file name: ${file}`);
  const [, version, name] = match;

  // Migration body without its own transaction lines (exactly one standalone begin; and commit; if present).
  const lines = migrationSql.replace(/\r/g, "").split("\n");
  const begins = lines.flatMap((l, i) => (/^\s*begin\s*;\s*$/i.test(l) ? [i] : []));
  const commits = lines.flatMap((l, i) => (/^\s*commit\s*;\s*$/i.test(l) ? [i] : []));
  if (begins.length > 1 || commits.length > 1 || begins.length !== commits.length) {
    throw new Error("Migration must have either no transaction lines or exactly one 'begin;' and one 'commit;'");
  }
  const body = lines.filter((_, i) => i !== begins[0] && i !== commits[0]).join("\n").trim();
  if (/^\s*(begin|commit|rollback)\s*;/im.test(body)) throw new Error("Migration body still contains transaction control");

  // Expected parity rows: section|items|fingerprint.
  const expected = expectedText.replace(/\r/g, "").trim().split("\n").map((row) => {
    const [section, items, fp] = row.split("|");
    if (!/^[a-z_]+$/.test(section) || !/^\d+$/.test(items) || !/^[0-9a-f]{32}$/.test(fp)) throw new Error(`Bad expected parity row: ${row}`);
    return { section, items: Number(items), fp };
  });
  const migrationsRow = expected.find((r) => r.section === "migrations");
  if (!migrationsRow) throw new Error("Expected parity has no migrations row");
  const before = migrationsRow.items - 1;

  const parityQuery = paritySql.replace(/\r/g, "").split("\n").filter((l) => !/^\s*--/.test(l)).join("\n").trim().replace(/;\s*$/, "");
  const stripBlock = stripCrSql.replace(/\r/g, "").match(/do \$strip\$[\s\S]*?\$strip\$;/)?.[0];
  if (!stripBlock) throw new Error("strip-cr.sql: DO block not found");
  const checks = checksSql === null ? null : checksSql.replace(/\r/g, "").split("\n").filter((l) => !/^\s*--/.test(l)).join("\n").trim().replace(/;\s*$/, "");

  const values = expected.map((r) => `('${r.section}', ${r.items}, '${r.fp}')`).join(",\n  ");
  return `-- FFH hosted apply: migration ${version}_${name}
-- GENERATED by scripts/hosted/build-apply.mjs from the files at the commit the Builder names. Do not edit.
-- Paste the WHOLE file into a new Supabase SQL Editor query and Run ONCE. One transaction: if any check fails you get
-- one error starting FFH_APPLY_FAIL that names every failed check, and NOTHING is applied. Success ends with a table
-- of PASS rows; paste that table back to the Builder.
begin;

create temp table ffh_apply_results(step int, check_name text, ok boolean, detail text);

-- 1. Pre-check: hosted is exactly at the previous migration and has not recorded this one.
do $pre$
declare n int;
begin
  select count(*) into n from supabase_migrations.schema_migrations;
  if n <> ${before} then
    raise exception 'FFH_APPLY_FAIL nothing was applied: pre-check expected ${before} recorded migrations, found %', n;
  end if;
  if exists (select 1 from supabase_migrations.schema_migrations where version = '${version}') then
    raise exception 'FFH_APPLY_FAIL nothing was applied: migration ${version} is already recorded';
  end if;
  insert into ffh_apply_results values (1, 'pre-check: ${before} migrations, ${version} not yet recorded', true, null);
end
$pre$;

-- 2. The migration.
${body}

-- 3. Record it.
insert into supabase_migrations.schema_migrations(version, name) values ('${version}', '${name}');
insert into ffh_apply_results values (2, 'migration ${version} applied and recorded', true, null);

-- 4. Paste repair (scripts/rls-local/strip-cr.sql): functions whose body picked up CR characters.
${stripBlock}
insert into ffh_apply_results
select 3, 'paste repair: no function body contains CR', count(*) = 0, count(*)::text || ' left'
from pg_proc p join pg_namespace n on n.oid = p.pronamespace
where n.nspname in ('public', 'private') and position(E'\\r' in p.prosrc) > 0;
${checks === null ? "" : `
-- 5. Phase checks (scripts/hosted/checks/${version}.sql).
insert into ffh_apply_results select 4, 'phase check: ' || c.check_name, c.ok, null from (
${checks}
) c;
`}
-- 6. Parity against scripts/rls-local/parity.expected.txt at this commit.
create temp table ffh_apply_parity as
${parityQuery};
insert into ffh_apply_results
select 5, 'parity: ' || e.section, p.items = e.items and p.fingerprint = e.fp,
       case when p.section is null then 'missing' when p.items = e.items and p.fingerprint = e.fp then null
            else p.items::text || '|' || p.fingerprint end
from (values
  ${values}
) e(section, items, fp)
left join ffh_apply_parity p on p.section = e.section;
insert into ffh_apply_results
select 5, 'parity: unexpected section ' || p.section, false, p.items::text || '|' || p.fingerprint
from ffh_apply_parity p
where p.section not in (${expected.map((r) => `'${r.section}'`).join(", ")});

-- 7. All or nothing.
do $fin$
declare bad text;
begin
  select string_agg(check_name || coalesce(' [' || detail || ']', ''), '; ' order by step, check_name) into bad
  from ffh_apply_results where not ok;
  if bad is not null then
    raise exception 'FFH_APPLY_FAIL nothing was applied: %', bad;
  end if;
end
$fin$;

commit;

select step, check_name, case when ok then 'PASS' else 'FAIL' end as result
from ffh_apply_results order by step, check_name;
`;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const args = process.argv.slice(2);
  const migrationPath = args.find((a) => !a.startsWith("--") && args[args.indexOf(a) - 1] !== "--expected" && args[args.indexOf(a) - 1] !== "--out");
  const flag = (name) => (args.includes(name) ? args[args.indexOf(name) + 1] : null);
  if (!migrationPath) {
    console.error("usage: node scripts/hosted/build-apply.mjs <migration.sql> [--expected <parity file>] [--out <file>]");
    process.exit(2);
  }
  const version = basename(migrationPath).split("_")[0];
  const checksPath = join(repo, "scripts/hosted/checks", `${version}.sql`);
  const sql = buildApply({
    migrationPath,
    migrationSql: readFileSync(resolve(migrationPath), "utf8"),
    paritySql: readFileSync(join(repo, "scripts/rls-local/parity.sql"), "utf8"),
    expectedText: readFileSync(resolve(flag("--expected") ?? join(repo, "scripts/rls-local/parity.expected.txt")), "utf8"),
    stripCrSql: readFileSync(join(repo, "scripts/rls-local/strip-cr.sql"), "utf8"),
    checksSql: existsSync(checksPath) ? readFileSync(checksPath, "utf8") : null,
  });
  const out = flag("--out");
  if (out) writeFileSync(out, sql); else process.stdout.write(sql);
}
